"""A Class for performing sequenced interactions to add a new Machine Characterization in a MOSOAIQ application"""

from ..interactions import dashboard
from ..interactions import machine_characterization

class MachineCharacterization():
    def __init__(self) -> None:
        pass

    def add_machine_location(self, locationName: str, locationCategory: str, locationType: str) -> None:
        dashboard.open_location_directories()
        machine_characterization.open_add_new_location()
        machine_characterization.type_location_details_name(locationName)
        machine_characterization.select_location_details_category(locationCategory)
        machine_characterization.select_location_details_type(locationType)
        machine_characterization.save_location_details()
        machine_characterization.close_location_directories()

    def import_MAC_Template(self, folderPath: str, fileName: str) -> None:
        dashboard.open_machine_characterization()
        machine_characterization.open_import_machine_characterization()
        machine_characterization.select_pc_desktop_import_path()
        machine_characterization.open_import_file_dropdown()
        machine_characterization.select_import_file_from_dropdown(fileName)
        machine_characterization.click_template_import_ok_button()

    def add_machine(self, machineName: str, templateName: str) -> None:
        dashboard.open_machine_characterization()
        machine_characterization.open_add_machine_characterization()
        machine_characterization.open_pick_reference_characterizations_window()
        machine_characterization.select_reference_template(templateName)
        machine_characterization.click_pick_reference_select_button()
        machine_characterization.select_machine(machineName)
        machine_characterization.click_copy_all_button()
        machine_characterization.click_add_machine_ok_button()

    def approve_machine(self, machineName: str) -> None:
        machine_characterization.click_option_in_characterization_view_list(machineName)
        machine_characterization.click_machine_characterization_approve_button()
        machine_characterization.enter_approval_password("elekta01")
        machine_characterization.click_approval_ok_button()